CREATE OR REPLACE FUNCTION public.ensure_user_wallet() RETURNS TABLE(id uuid,balance numeric,currency text,updated_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_user_id uuid:=auth.uid(); BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; INSERT INTO public.profiles(id,email,display_name) VALUES(v_user_id,auth.jwt()->>'email',COALESCE(auth.jwt()->'user_metadata'->>'display_name',split_part(COALESCE(auth.jwt()->>'email',''),'@',1))) ON CONFLICT ON CONSTRAINT profiles_pkey DO UPDATE SET email=EXCLUDED.email,updated_at=now(); INSERT INTO public.wallets(user_id) VALUES(v_user_id) ON CONFLICT ON CONSTRAINT wallets_user_id_key DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(v_user_id,'user') ON CONFLICT ON CONSTRAINT user_roles_user_id_role_key DO NOTHING; RETURN QUERY SELECT w.id,w.balance,w.currency,w.updated_at FROM public.wallets w WHERE w.user_id=v_user_id; END $$;